import{_ as s,a0 as d,w as i,s as l,I as r,x as t,a1 as o,A as n,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"RHCSA 系列（六）: 使用 ACL（訪問控制列表) 和掛載 Samba/NFS 共享 | LCTT x X-CMD","titleTemplate":false,"description":"RHCSA 系列（六）: 使用 ACL（訪問控制列表) 和掛載 Samba/NFS 共享 | LCTT (RHCSA Series) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"RHCSA 系列（六）: 使用 ACL（訪問控制列表) 和掛載 Samba/NFS 共享 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"RHCSA 系列（六）: 使用 ACL（訪問控制列表) 和掛載 Samba/NFS 共享 | LCTT (RHCSA Series) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"RHCSA Series/RHCSA Series--Part 07--Using ACLs (Access Control Lists) and Mounting Samba or NFS Shares","title":"RHCSA 系列（六）: 使用 ACL（訪問控制列表) 和掛載 Samba/NFS 共享","tag":"RHCSA Series","desc":""},"relativePath":"RHCSA Series/RHCSA Series--Part 07--Using ACLs (Access Control Lists) and Mounting Samba or NFS Shares.md","filePath":"[post].md"}'),m={name:"RHCSA Series/RHCSA Series--Part 07--Using ACLs (Access Control Lists) and Mounting Samba or NFS Shares.md"};function c(u,e,S,C,f,g){const a=d("Link");return i(),l("div",null,[e[21]||(e[21]=r("h1",{id:"rhcsa-系列-六-使用-acl-訪問控制列表-和掛載-samba-nfs-共享",tabindex:"-1"},[t("RHCSA 系列（六）: 使用 ACL（訪問控制列表) 和掛載 Samba/NFS 共享 "),r("a",{class:"header-anchor",href:"#rhcsa-系列-六-使用-acl-訪問控制列表-和掛載-samba-nfs-共享","aria-label":"Permalink to “RHCSA 系列（六）: 使用 ACL（訪問控制列表) 和掛載 Samba/NFS 共享”"},"​")],-1)),r("p",null,[e[1]||(e[1]=t("在上一篇文章(",-1)),o(a,{href:"https://linux.cn/article-6257-1.html"},{default:n(()=>[...e[0]||(e[0]=[t("RHCSA 系列（六）",-1)])]),_:1}),e[2]||(e[2]=t(")中，我們解釋瞭如何使用 parted 和 ssm 來設置和配置本地系統存儲。",-1))]),e[22]||(e[22]=p('<p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Configure-ACLs-and-Mounting-NFS-Samba-Shares.png" alt="配置 ACL 及掛載 NFS/Samba 共享"></p><p><em>RHCSA 系列: 配置 ACL 及掛載 NFS/Samba 共享 – Part 7</em></p><p>我們也討論瞭如何創建和在系統啓動時使用一個密碼來掛載加密的卷。另外，我們告誡過你要避免在掛載的文件系統上執行危險的存儲管理操作。記住了這點後，現在，我們將回顧在 RHEL 7 中最常使用的文件系統格式，然後將涵蓋有關手動或自動掛載、使用和卸載網絡文件系統（CIFS 和 NFS）的話題以及在你的操作系統上實現訪問控制列表（Access Control List）的使用。</p><h4 id="前提條件" tabindex="-1">前提條件 <a class="header-anchor" href="#前提條件" aria-label="Permalink to “前提條件”">​</a></h4><p>在進一步深入之前，請確保你可使用 Samba 服務和 NFS 服務（注意在 RHEL 7 中 NFSv2 已不再被支持）。</p><p>在本次指導中，我們將使用一個IP 地址為 192.168.0.10 且同時運行着 Samba 服務和 NFS 服務的機器來作為服務器，使用一個 IP 地址為 192.168.0.18 的 RHEL 7 機器來作為客户端。在這篇文章的後面部分，我們將告訴你在客户端上你需要安裝哪些軟件包。</p><h3 id="rhel-7-中的文件系統格式" tabindex="-1">RHEL 7 中的文件系統格式 <a class="header-anchor" href="#rhel-7-中的文件系統格式" aria-label="Permalink to “RHEL 7 中的文件系統格式”">​</a></h3><p>從 RHEL 7 開始，由於 XFS 的高性能和可擴展性，它已經被作為所有的架構中的默認文件系統。根據 Red Hat 及其合作伙伴在主流硬件上執行的最新測試，當前 XFS 已支持最大為 500 TB 大小的文件系統。</p><p>另外，XFS 啓用了 <code>user_xattr</code>（擴展用户屬性） 和 <code>acl</code>（POSIX 訪問控制列表）來作為默認的掛載選項，而不像 ext3 或 ext4（對於 RHEL 7 來説，ext2 已過時），這意味着當掛載一個 XFS 文件系統時，你不必顯式地在命令列或 /etc/fstab 中指定這些選項（假如你想在後一種情況下禁用這些選項，你必須顯式地使用 <code>no_acl</code> 和 <code>no_user_xattr</code>）。</p><p>請記住擴展用户屬性可以給文件和目錄指定，用來存儲任意的額外信息如 mime 類型，字符集或文件的編碼，而用户屬性中的訪問權限由一般的文件權限位來定義。</p><h4 id="訪問控制列表" tabindex="-1">訪問控制列表 <a class="header-anchor" href="#訪問控制列表" aria-label="Permalink to “訪問控制列表”">​</a></h4>',11)),r("p",null,[e[4]||(e[4]=t("作為一名系統管理員，無論你是新手還是專家，你一定非常熟悉與文件和目錄有關的常規訪問權限，這些權限為所有者，所有組和“世界”（所有的其他人）指定了特定的權限（可讀，可寫及可執行）。但如若你需要稍微更新下你的記憶，請參考 ",-1)),o(a,{href:"https://access.redhat.com/documentation/en-US/Red_Hat_Enterprise_Linux/7/html/Storage_Administration_Guide/ch-acls.html"},{default:n(()=>[...e[3]||(e[3]=[t("RHCSA 系列（三）",-1)])]),_:1}),e[5]||(e[5]=t(".",-1))]),e[23]||(e[23]=p(`<p>但是，由於標準的 <code>ugo/rwx</code> 集合並不允許為不同的用户配置不同的權限，所以 ACL 便被引入了進來，為的是為文件和目錄定義更加詳細的訪問權限，而不僅僅是這些特別指定的特定權限。</p><p>事實上， ACL 定義的權限是由文件權限位所特別指定的權限的一個超集。下面就讓我們看看這個轉換是如何在真實世界中被應用的吧。</p><ol><li><p>存在兩種類型的 ACL：訪問 ACL，可被應用到一個特定的文件或目錄上；以及默認 ACL，只可被應用到一個目錄上。假如目錄中的文件沒有 ACL，則它們將繼承它們的父目錄的默認 ACL 。</p></li><li><p>從一開始， ACL 就可以為每個用户，每個組或不在文件所屬組中的用户配置相應的權限。</p></li><li><p>ACL 可使用 <code>setfacl</code> 來設置（和移除），可相應地使用 -m 或 -x 選項。</p></li></ol><p>例如，讓我們創建一個名為 tecmint 的組，並將用户 johndoe 和 davenull 加入該組：</p><pre><code># groupadd tecmint
# useradd johndoe
# useradd davenull
# usermod -a -G tecmint johndoe
# usermod -a -G tecmint davenull
</code></pre><p>並且讓我們檢驗這兩個用户都已屬於追加的組 tecmint：</p><pre><code># id johndoe
# id davenull
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Verify-Users.png" alt="檢驗用户"></p><p><em>檢驗用户</em></p><p>現在，我們在 /mnt 下創建一個名為 playground 的目錄，並在該目錄下創建一個名為 testfile.txt 的文件。我們將設定該文件的屬組為 tecmint，並更改它的默認 <code>ugo/rwx</code> 權限為 770（即賦予該文件的屬主和屬組可讀、可寫和可執行權限）：</p><pre><code># mkdir /mnt/playground
# touch /mnt/playground/testfile.txt
# chown :tecmint /mnt/playground/testfile.txt
# chmod 770 /mnt/playground/testfile.txt
</code></pre><p>接着，依次切換為 johndoe 和 davenull 用户，並在文件中寫入一些信息：</p><pre><code># su johndoe
$ echo &quot;My name is John Doe&quot; &gt; /mnt/playground/testfile.txt
$ su davenull
$ echo &quot;My name is Dave Null&quot; &gt;&gt; /mnt/playground/testfile.txt
</code></pre><p>到目前為止，一切正常。現在我們讓用户 gacanepa 來向該文件執行寫操作 – 則寫操作將會失敗，這是可以預料的。</p><pre><code>$ su gacanepa
$ echo &quot;My name is Gabriel Canepa&quot; &gt;&gt; /mnt/playground/testfile.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/User-Permissions.png" alt="管理用户的權限"></p><p><em>管理用户的權限</em></p><p>但實際上我們需要用户 gacanepa（他不是組 tecmint 的成員）在文件 /mnt/playground/testfile.txt 上有寫權限，那又該怎麼辦呢？首先映入你腦海裏的可能是將該用户添加到組 tecmint 中。但那將使得他在所有該組具有寫權限位的文件上均擁有寫權限，但我們並不想這樣，我們只想他能夠在文件 /mnt/playground/testfile.txt 上有寫權限。</p><p>現在，讓我們給用户 gacanepa 在 /mnt/playground/testfile.txt 文件上有讀和寫權限。</p><p>以 root 的身份運行如下命令：</p><pre><code># setfacl -R -m u:gacanepa:rwx /mnt/playground
</code></pre><p>則你將成功地添加一條 ACL，允許 gacanepa 對那個測試文件可寫。然後切換為 gacanepa 用户，並再次嘗試向該文件寫入一些信息：</p><pre><code>$ echo &quot;My name is Gabriel Canepa&quot; &gt;&gt; /mnt/playground/testfile.txt
</code></pre><p>要觀察一個特定的文件或目錄的 ACL，可以使用 <code>getfacl</code> 命令：</p><pre><code># getfacl /mnt/playground/testfile.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Check-ACL-of-File.png" alt="檢查文件的 ACL"></p><p><em>檢查文件的 ACL</em></p><p>要為目錄設定默認 ACL（它的內容將被該目錄下的文件繼承，除非另外被覆寫），在規則前添加 <code>d:</code>並特別指定一個目錄名，而不是文件名：</p><pre><code># setfacl -m d:o:r /mnt/playground
</code></pre><p>上面的 ACL 將允許不在屬組中的用户對目錄 /mnt/playground 中的內容有讀權限。請注意觀察這次更改前後 <code>getfacl /mnt/playground</code> 的輸出結果的不同：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Set-Default-ACL-in-Linux.png" alt="在 Linux 中設定默認 ACL"></p><p><em>在 Linux 中設定默認 ACL</em></p>`,32)),r("p",null,[o(a,{href:"https://access.redhat.com/documentation/en-US/Red_Hat_Enterprise_Linux/7/html/Storage_Administration_Guide/ch-acls.html"},{default:n(()=>[...e[6]||(e[6]=[t("在官方的 RHEL 7 存儲管理指導手冊的第 20 章",-1)])]),_:1}),e[7]||(e[7]=t(" 中提供了更多有關 ACL 的例子，我極力推薦你看一看它並將它放在身邊作為參考。",-1))]),e[24]||(e[24]=p(`<h4 id="掛載-nfs-網絡共享" tabindex="-1">掛載 NFS 網絡共享 <a class="header-anchor" href="#掛載-nfs-網絡共享" aria-label="Permalink to “掛載 NFS 網絡共享”">​</a></h4><p>要顯示你服務器上可用的 NFS 共享的列表，你可以使用帶有 -e 選項的 <code>showmount</code> 命令，再跟上機器的名稱或它的 IP 地址。這個工具包含在 <code>nfs-utils</code> 軟件包中：</p><pre><code># yum update &amp;&amp; yum install nfs-utils
</code></pre><p>接着運行：</p><pre><code># showmount -e 192.168.0.10
</code></pre><p>則你將得到一個在 192.168.0.10 上可用的 NFS 共享的列表：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Mount-NFS-Shares.png" alt="檢查可用的 NFS 共享"></p><p><em>檢查可用的 NFS 共享</em></p><p>要按照需求在本地客户端上使用命令列來掛載 NFS 網絡共享，可使用下面的語法：</p><pre><code># mount -t nfs -o [options] remote_host:/remote/directory /local/directory
</code></pre><p>其中，在我們的例子中，對應為：</p><pre><code># mount -t nfs 192.168.0.10:/NFS-SHARE /mnt/nfs
</code></pre><p>若你得到如下的錯誤信息：<code>Job for rpc-statd.service failed. See &quot;systemctl status rpc-statd.service&quot; and &quot;journalctl -xn&quot; for details.</code>，請確保 <code>rpcbind</code> 服務被啓用且已在你的系統中啓動了。</p><pre><code># systemctl enable rpcbind.socket
# systemctl restart rpcbind.service
</code></pre><p>接着重啓。這就應該達到了上面的目的，且你將能夠像先前解釋的那樣掛載你的 NFS 共享了。若你需要在系統啓動時自動掛載 NFS 共享，可以向 /etc/fstab 文件添加一個有效的條目：</p><pre><code>remote_host:/remote/directory /local/directory nfs options 0 0
</code></pre><p>上面的變量 remote_host, /remote/directory, /local/directory 和 options(可選) 和在命令列中手動掛載一個 NFS 共享時使用的一樣。按照我們前面的例子，對應為：</p><pre><code>192.168.0.10:/NFS-SHARE /mnt/nfs nfs defaults 0 0
</code></pre><h4 id="掛載-cifs-samba-網絡共享" tabindex="-1">掛載 CIFS (Samba) 網絡共享 <a class="header-anchor" href="#掛載-cifs-samba-網絡共享" aria-label="Permalink to “掛載 CIFS (Samba) 網絡共享”">​</a></h4><p>Samba 代表一個特別的工具，使得在由 *nix 和 Windows 機器組成的網絡中進行網絡共享成為可能。要顯示可用的 Samba 共享，可使用帶有 -L 選項的 smbclient 命令，再跟上機器的名稱或它的 IP 地址。這個工具包含在 samba_client 軟件包中：</p><p>你將被提示在遠程主機上輸入 root 用户的密碼：</p><pre><code># smbclient -L 192.168.0.10
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Check-Samba-Shares.png" alt="檢查 Samba 共享"></p><p><em>檢查 Samba 共享</em></p><p>要在本地客户端上掛載 Samba 網絡共享，你需要已安裝好 cifs-utils 軟件包：</p><pre><code># yum update &amp;&amp; yum install cifs-utils
</code></pre><p>然後在命令列中使用下面的語法：</p><pre><code># mount -t cifs -o credentials=/path/to/credentials/file //remote_host/samba_share /local/directory
</code></pre><p>其中，在我們的例子中，對應為：</p><pre><code># mount -t cifs -o credentials=~/.smbcredentials //192.168.0.10/gacanepa /mnt/samba
</code></pre><p>其中 <code>.smbcredentials</code> 的內容是：</p><pre><code>username=gacanepa
password=XXXXXX
</code></pre><p>它是一個位於 root 用户的家目錄(/root/) 中的隱藏文件，其權限被設置為 600，所以除了該文件的屬主外，其他人對該文件既不可讀也不可寫。</p><p>請注意 samba_share 是 Samba 共享的名稱，由上面展示的 <code>smbclient -L remote_host</code> 所返回。</p><p>現在，若你需要在系統啓動時自動地使得 Samba 分享可用，可以向 /etc/fstab 文件添加一個像下面這樣的有效條目：</p><pre><code>//remote_host:/samba_share /local/directory cifs options 0 0
</code></pre><p>上面的變量 remote_host, /remote/directory, /local/directory 和 options(可選) 和在命令列中手動掛載一個 Samba 共享時使用的一樣。按照我們前面的例子中所給的定義，對應為：</p><pre><code>//192.168.0.10/gacanepa /mnt/samba  cifs credentials=/root/smbcredentials,defaults 0 0
</code></pre><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>在這篇文章中，我們已經解釋瞭如何在 Linux 中設置 ACL，並討論瞭如何在一個 RHEL 7 客户端上掛載 CIFS 和 NFS 網絡共享。</p><p>我建議你去練習這些概念，甚至混合使用它們（試着在一個掛載的網絡共享上設置 ACL），直至你感覺掌握了。假如你有問題或評論，請隨時隨意地使用下面的評論框來聯繫我們。另外，請隨意通過你的社交網絡分享這篇文章。</p><hr>`,42)),r("p",null,[e[9]||(e[9]=t("via: ",-1)),o(a,{href:"http://www.tecmint.com/rhcsa-exam-configure-acls-and-mount-nfs-samba-shares/"},{default:n(()=>[...e[8]||(e[8]=[t("http://www.tecmint.com/rhcsa-exam-configure-acls-and-mount-nfs-samba-shares/",-1)])]),_:1})]),r("p",null,[e[13]||(e[13]=t("作者：",-1)),o(a,{href:"http://www.tecmint.com/author/gacanepa/"},{default:n(()=>[...e[10]||(e[10]=[t("Gabriel Cánepa",-1)])]),_:1}),e[14]||(e[14]=t(" 譯者：",-1)),o(a,{href:"https://github.com/FSSlc"},{default:n(()=>[...e[11]||(e[11]=[t("FSSlc",-1)])]),_:1}),e[15]||(e[15]=t(" 校對：",-1)),o(a,{href:"https://github.com/wxy"},{default:n(()=>[...e[12]||(e[12]=[t("wxy",-1)])]),_:1})]),r("p",null,[e[18]||(e[18]=t("本文由 ",-1)),o(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[16]||(e[16]=[t("LCTT",-1)])]),_:1}),e[19]||(e[19]=t(" 原創翻譯，",-1)),o(a,{href:"https://linux.cn/"},{default:n(()=>[...e[17]||(e[17]=[t("Linux中國",-1)])]),_:1}),e[20]||(e[20]=t(" 榮譽推出",-1))])])}const L=s(m,[["render",c]]);export{b as __pageData,L as default};
